import type { HTTPError } from "../../error.ts";

export const kProblem = "~problem";

export interface ProblemMark {
  type?: string;
  instance?: string;
  detail?: string;
}

// The mark is a render function (read by `errorResponse` in `response.ts`) so the
// title table is only bundled for apps that use `problem()`.
export function markProblem(error: HTTPError, mark: ProblemMark): void {
  Object.defineProperty(error, kProblem, {
    value: () => problemBody(error, mark),
    enumerable: false,
  });
}

function problemBody(error: HTTPError, mark: ProblemMark): Record<string, unknown> {
  const unhandled = error.unhandled;
  const title = error.statusText || STATUS_TITLES[error.status];
  const body: Record<string, unknown> = {};

  // Extensions first so standard members take precedence on collision
  if (!unhandled) {
    if (error.data !== undefined) {
      body.data = error.data;
    }
    Object.assign(body, error.body);
  }

  body.type = mark.type ?? "about:blank";
  body.status = error.status;
  if (title) {
    body.title = title;
  } else {
    delete body.title;
  }
  if (mark.detail && !unhandled) {
    body.detail = mark.detail;
  } else {
    delete body.detail;
  }
  if (mark.instance) {
    body.instance = mark.instance;
  } else {
    delete body.instance;
  }
  return body;
}

// prettier-ignore
const STATUS_TITLES: Record<number, string> = {
  400: "Bad Request", 401: "Unauthorized", 402: "Payment Required", 403: "Forbidden",
  404: "Not Found", 405: "Method Not Allowed", 406: "Not Acceptable", 408: "Request Timeout",
  409: "Conflict", 410: "Gone", 411: "Length Required", 412: "Precondition Failed",
  413: "Content Too Large", 414: "URI Too Long", 415: "Unsupported Media Type",
  416: "Range Not Satisfiable", 417: "Expectation Failed", 418: "I'm a Teapot",
  421: "Misdirected Request", 422: "Unprocessable Content", 423: "Locked",
  424: "Failed Dependency", 425: "Too Early", 426: "Upgrade Required",
  428: "Precondition Required", 429: "Too Many Requests", 431: "Request Header Fields Too Large",
  451: "Unavailable For Legal Reasons", 500: "Internal Server Error", 501: "Not Implemented",
  502: "Bad Gateway", 503: "Service Unavailable", 504: "Gateway Timeout",
  505: "HTTP Version Not Supported", 507: "Insufficient Storage", 508: "Loop Detected",
  511: "Network Authentication Required",
};

